// s3StreamDecoder incrementally decodes records from the "Records" array of an S3
// CloudTrail log. It implements encoding.LogsDecoder.
type s3StreamDecoder struct {
	u          *CloudTrailLogUnmarshaler
	decoder    *gojson.Decoder
	flushItems int64
	// count is the number of records processed so far, seeded with the initial
	// offset (the number of skipped records).
	count int64
}

// newS3StreamDecoder consumes the JSON preamble ('{', "Records", '['), skips the
// records requested via WithOffset, and returns a streaming decoder positioned at
// the first record to decode.
func (u *CloudTrailLogUnmarshaler) newS3StreamDecoder(decoder *gojson.Decoder, opts encoding.DecoderOptions) (encoding.LogsDecoder, error) {
	// Check opening bracket
	if token, err := decoder.Token(); err != nil || token != gojson.Delim('{') {
		return nil, fmt.Errorf("expected '{': %w", err)
	}

	// Move to Records array
	if _, err := decoder.Token(); err != nil {
		return nil, fmt.Errorf("expected 'Records' key: %w", err)
	}

	// Check for array opening
	if token, err := decoder.Token(); err != nil || token != gojson.Delim('[') {
		return nil, fmt.Errorf("expected '[': %w", err)
	}

	// Skip the first opts.Offset records.
	for i := int64(0); i < opts.Offset && decoder.More(); i++ {
		var skip CloudTrailRecord
		if err := decoder.Decode(&skip); err != nil {
			return nil, fmt.Errorf("failed to skip record: %w", err)
		}
	}

	return &s3StreamDecoder{
		u:          u,
		decoder:    decoder,
		flushItems: opts.FlushItems,
		count:      opts.Offset,
	}, nil
}

func (s *s3StreamDecoder) DecodeLogs() (plog.Logs, error) {
	if !s.decoder.More() {
		return plog.NewLogs(), io.EOF
	}

	logs, resourceLogs, scopeLogs := s.u.createLogs()

	logRecords := scopeLogs.LogRecords()

	init := true
	var batchCount int64
	for s.decoder.More() {
		var record CloudTrailRecord
		if err := s.decoder.Decode(&record); err != nil {
			return plog.Logs{}, err
		}

		if init {
			s.u.setResourceAttributes(resourceLogs.Resource().Attributes(), record)
			init = false
		}

		logRecord := logRecords.AppendEmpty()
		if err := s.u.setLogRecord(logRecord, &record); err != nil {
			return plog.Logs{}, err
		}

		s.count++
		batchCount++

		if s.flushItems > 0 && batchCount >= s.flushItems {
			break
		}
	}

	return logs, nil
}

func (s *s3StreamDecoder) Offset() int64 {
	return s.count
}

// singleBatchDecoder wraps a payload that is decoded as a single batch (CloudWatch
