type singleBatchDecoder struct {
	logs   plog.Logs
	offset int64
	done   bool
}

// newSingleBatchDecoder eagerly decodes the single-document payload so that the
// number of bytes consumed can be reported via Offset. A non-zero initial offset
// signals that the batch was already consumed, so DecodeLogs returns io.EOF.
func (*CloudTrailLogUnmarshaler) newSingleBatchDecoder(
	decoder *gojson.Decoder,
	opts encoding.DecoderOptions,
	decodeFn func(*gojson.Decoder) (plog.Logs, error),
) (encoding.LogsDecoder, error) {
	logs, err := decodeFn(decoder)
	if err != nil {
		return nil, err
	}

	return &singleBatchDecoder{
		logs:   logs,
		offset: decoder.InputOffset(),
		done:   opts.Offset != 0,
	}, nil
}

func (d *singleBatchDecoder) DecodeLogs() (plog.Logs, error) {
	if d.done {
		return plog.NewLogs(), io.EOF
	}
	d.done = true
	return d.logs, nil
}

func (d *singleBatchDecoder) Offset() int64 {
	return d.offset
}

